  ('rema', 'REMA 1000', 'https://www.rema.no', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'SITEMAP_DISCOVERY', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://www.rema.no/oppskrifter/tiktok-oppskrifter/tortilla-kebabspyd/', 'https://www.rema.no/oppskrifter/middagstips/', 'https://www.rema.no/oppskrifter/tradisjonsmat/']::text[], 'Rike kildekategorier (råvare/måltid/anledning/sesong/retttype/kjøkken) — mappes til vår taksonomi, aldri adoptert rått.'),
