  ('meny', 'MENY', 'https://meny.no', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'SITEMAP_DISCOVERY', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://meny.no/oppskrifter/pizza/pinsa-med-chorizo', 'https://meny.no/oppskrifter/middagstips']::text[], 'Stor oppdagelseskilde. Bruk listesider til oppdaging; hent detaljer kun ved behov — aldri bulk fordi det er mulig.'),
  ('kiwi', 'KIWI', 'https://kiwi.no', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'SITEMAP_DISCOVERY', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://kiwi.no/billig-middag', 'https://kiwi.no/oppskrifter', 'https://kiwi.no/oppskrifter/supper']::text[], 'Inspirasjon + fremtidig tilbudskontekst. En KIWI-oppskrift binder ALDRI handelen til KIWI — husholdningen kan kjøpe alt på Coop Extra.'),
  ('coop', 'Coop', 'https://www.coop.no', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'SITEMAP_DISCOVERY', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://www.coop.no/inspirasjon/middag', 'https://www.coop.no/oppskrifter', 'https://www.coop.no/oppskrifter/suppe']::text[], 'Filtre (nasjonalitet/hovedråvare/type/sesong/tid/vanskelighet) mappes til vår taksonomi. «Kjøttdeig» i oppskrift er ingrediens; «Xtra kjøttdeig» er produktvalg — hold begrepene adskilt.'),
  ('oda', 'Oda', 'https://oda.com', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'PUBLIC_JSON', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://oda.com/no/about/middagstips/', 'https://oda.com/no/recipes/']::text[], 'Modellen deres (oppskrift→porsjoner→ingredienser→varer) er den vi vil speile — men i VÅRT Item/Kassalapp-system. Lagre aldri Odas handlekurv.'),
  ('gilde', 'Gilde', 'https://www.gilde.no', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'SITEMAP_DISCOVERY', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://www.gilde.no/konsept/middagstips', 'https://www.gilde.no/oppskrifter', 'https://www.gilde.no/oppskrifter/tradisjonsmat', 'https://www.gilde.no/oppskrifter/supper-og-gryter']::text[], 'Kjøttbasert og tradisjonsmat. «Kvernet storfekjøtt» hardbindes aldri til Gilde-produkt — produktmatchingen velger etter preferanse og pris.'),
  ('frukt', 'FRUKT.no', 'https://www.frukt.no', 'NO', 'nb', 80, array['STRUCTURED_DATA', 'SITEMAP_DISCOVERY', 'HTML_RECIPE', 'LINK_DISCOVERY_ONLY']::text[], true, true, true, true, true, false, false, true, 'unreviewed', 'allowed', array['https://www.frukt.no/tema/middag/', 'https://www.frukt.no/oppskrifter/enkel-blomkalsuppe/', 'https://www.frukt.no/oppskrifter/lys-lapskaus/']::text[], 'Positivt signal når vi vil ha mer grønnsaker, familievennlig, billig eller rask hverdag — kildetags (Rask/Billig/Sunn/Familievennlig) går rett i scoringen.'),
